class Solution:
    def parseTernary(self, expression: str) -> str:
        def parse(i):
            val = expression[i]
            i += 1
            if i == len(expression) or expression[i] != '?':
                return val, i
            true_val, j = parse(i + 1)
            false_val, k = parse(j + 1)
            return (true_val if val == 'T' else false_val), k
        return parse(0)[0]

