class Solution:
    def parseTernary(self, expression: str) -> str:
        stack = []
        for ch in reversed(expression):
            if stack and stack[-1] == '?':
                stack.pop()
                first = stack.pop()
                stack.pop()
                second = stack.pop()
                stack.append(first if ch == 'T' else second)
            else:
                stack.append(ch)
        return stack[-1]

