class Solution:
    def parseTernary(self, expression: str) -> str:
        def skip(i):
            depth = 0
            while i < len(expression):
                if expression[i] == '?':
                    depth += 1
                elif expression[i] == ':':
                    if depth == 0:
                        return i + 1
                    depth -= 1
                i += 1
            return i
        def eval_at(i):
            if i + 1 >= len(expression) or expression[i + 1] != '?':
                return expression[i]
            if expression[i] == 'T':
                return eval_at(i + 2)
            return eval_at(skip(i + 2))
        return eval_at(0)

